#include <string>

class Shuttle {
public:
    explicit Shuttle(std::string destination) : destination_(destination) {}

    void setDestination(const std::string& destination) {
        destination_ = destination;
    }

    const std::string& destination() const {
        return destination_;
    }

private:
    std::string destination_;
};

class ArrivalBoard {
public:
    ArrivalBoard() : watched_(nullptr) {}

    void watch(Shuttle& shuttle) {
        watched_ = &shuttle;
    }

    bool isWatching() const {
        return watched_ != nullptr;
    }

    std::string currentDestination() const {
        return watched_ == nullptr ? "No shuttle selected" : watched_->destination();
    }

private:
    Shuttle* watched_;
};
